output_text:
[
  {
    "id": "no_carts_single_file",
    "text": "Shopping carts are prohibited in single-file product aisles between shelves.",
    "abstraction": {
      "state_properties": {
        "betweenFacingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileProductAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileProductAisle"
        ]
      }
    }
  },
  {
    "id": "drop_cart_before_single_file",
    "text": "A shopper must not move a cart into a single-file product aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileProductAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileProductAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "recover_parked_cart",
    "text": "Whenever a shopper parks a cart to make an on-foot aisle excursion, they are obliged to recover the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "cartParkingMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "recoverCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "cartParkingMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "recoverCart"
    }
  },
  {
    "id": "no_roaming_without_cart",
    "text": "Without a cart, a shopper may move only inside the narrow retrieval aisle or at its cart-parking mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileProductAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "onFootRetrievalZone": {
          "or": [
            "singleFileProductAisle",
            "cartParkingMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "onFootRetrievalZone"
          }
        ]
      }
    }
  },
  {
    "id": "cart_for_open_shelf_interactions",
    "text": "Shelf interactions in cart-accessible open aisles must be done while holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileProductAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileProductAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "openShelfFace",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "park_only_at_aisle_mouths",
    "text": "Carts may be parked only at the wide mouths of narrow retrieval aisles.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "cartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "return_after_single_file_pickup",
    "text": "After collecting an item on foot inside a single-file product aisle, the shopper must return to and reclaim the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileProductAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "onFootSingleFilePickup": {
          "pre": {
            "and": [
              "INTERACT",
              "singleFileProductAisle",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        },
        "recoverCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "cartParkingMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootSingleFilePickup",
      "discharge": "recoverCart"
    }
  },
  {
    "id": "exit_with_cart_from_exit_lane",
    "text": "The shopper may exit only from the wide exit lane while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "wideExitLane": {
          "and": [
            "at(11,7)",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "or": [
              {
                "not": "hasCart"
              },
              {
                "not": "wideExitLane"
              }
            ]
          }
        ]
      }
    }
  }
]
